const items = $input.all();
if (!items || items.length === 0) return [];
return [items[0]];

// Build booking confirmation email
// Data comes from Webhook body + DB: Get Customer response
const wb    = $('Webhook: Confirm Booking').first().json.body || {};
const custR = $input.first().json;

// Customer fields — prefer DB response, fall back to webhook body
const customer_name  = custR?.data?.full_name   || custR?.full_name   || wb.customer_name  || 'Valued Customer';
const customer_email = custR?.data?.email        || custR?.email       || wb.customer_email || '';

if (!customer_email) return [];   // no email — skip gracefully

const fmt     = n  => '£' + parseFloat(n || 0).toFixed(2);
const fmtDate = d  => {
  if (!d) return '—';
  const dt = new Date(String(d).slice(0,10) + 'T00:00:00');
  return dt.toLocaleDateString('en-GB', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
};

// Extract booking details from webhook body
const total       = parseFloat(wb.total_amount  || 0);
const balanceDue  = parseFloat(wb.balance_due   || 0);
const deposit     = parseFloat(wb.deposit_amount || Math.max(0, total - balanceDue));
const rooms       = Array.isArray(wb.rooms) ? wb.rooms : [];
const roomList    = rooms.length ? rooms.map(r => r.name || r).join(', ') : 'Your reserved space';
const eventDate   = wb.event_date  || wb.date_from  || custR?.data?.event_date  || null;
const startTime   = wb.start_time  || custR?.data?.start_time  || null;
const endTime     = wb.end_time    || custR?.data?.end_time    || null;
const eventType   = wb.event_type  || custR?.data?.event_type  || 'Event';
const guestCount  = wb.guest_count || wb.guests || custR?.data?.guests_count || null;
const payMethod   = (wb.payment_method || 'cash').toLowerCase();
const isDepositOnly = deposit > 0 && balanceDue > 0;

const payMethodLabel = {
  'cash':         'Cash',
  'bacs':         'Bank Transfer (BACS)',
  'bank_transfer':'Bank Transfer (BACS)',
  'cheque':       'Cheque',
  'card':         'Card Terminal',
  'stripe':       'Online Card Payment'
}[payMethod] || payMethod;

const subject = `✅ Booking Confirmed — ${fmtDate(eventDate)} | VenueDesk`;

const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head>
<body style="margin:0;padding:0;background:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
  <div style="max-width:600px;margin:0 auto;padding:32px 16px;">
    <div style="background:linear-gradient(135deg,#10b981 0%,#059669 100%);border-radius:12px 12px 0 0;padding:28px 32px;text-align:center;">
      <p style="margin:0 0 4px;color:rgba(255,255,255,.8);font-size:11px;letter-spacing:2px;text-transform:uppercase;">VenueDesk · Booking System</p>
      <h1 style="margin:0 0 6px;color:#fff;font-size:22px;font-weight:700;">✅ Booking Confirmed</h1>
      <p style="margin:0;color:rgba(255,255,255,.9);font-size:14px;">Your venue reservation is secured</p>
    </div>
    <div style="background:#fff;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 12px 12px;padding:32px;">
      <p style="margin:0 0 20px;color:#111827;font-size:15px;">Hi <strong>${customer_name}</strong>,</p>
      <p style="margin:0 0 20px;color:#4b5563;font-size:14px;line-height:1.65;">
        Great news! Your venue booking has been confirmed by our team. 
        Here's a summary of your reservation:
      </p>

      <!-- Booking Details -->
      <div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;padding:20px;margin-bottom:24px;">
        <h3 style="margin:0 0 14px;color:#111827;font-size:14px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;">📋 Booking Details</h3>
        <table style="width:100%;border-collapse:collapse;font-size:13px;">
          ${eventDate ? `<tr><td style="padding:5px 0;color:#6b7280;width:40%;">Date</td><td style="padding:5px 0;color:#111827;font-weight:600;">${fmtDate(eventDate)}</td></tr>` : ''}
          ${(startTime && endTime) ? `<tr><td style="padding:5px 0;color:#6b7280;">Time</td><td style="padding:5px 0;color:#111827;font-weight:600;">${String(startTime).slice(0,5)} – ${String(endTime).slice(0,5)}</td></tr>` : ''}
          <tr><td style="padding:5px 0;color:#6b7280;">Space</td><td style="padding:5px 0;color:#111827;font-weight:600;">${roomList}</td></tr>
          ${eventType ? `<tr><td style="padding:5px 0;color:#6b7280;">Event Type</td><td style="padding:5px 0;color:#111827;font-weight:600;">${eventType}</td></tr>` : ''}
          ${guestCount ? `<tr><td style="padding:5px 0;color:#6b7280;">Guests</td><td style="padding:5px 0;color:#111827;font-weight:600;">${guestCount}</td></tr>` : ''}
        </table>
      </div>

      <!-- Payment Summary -->
      <div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:10px;padding:20px;margin-bottom:24px;">
        <h3 style="margin:0 0 14px;color:#065f46;font-size:14px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;">💳 Payment Summary</h3>
        <table style="width:100%;border-collapse:collapse;font-size:13px;">
          <tr><td style="padding:5px 0;color:#065f46;width:40%;">Total Hire Fee</td><td style="padding:5px 0;color:#111827;font-weight:700;">${fmt(total)}</td></tr>
          ${deposit > 0 ? `<tr><td style="padding:5px 0;color:#065f46;">Deposit Paid</td><td style="padding:5px 0;color:#10b981;font-weight:700;">${fmt(deposit)} via ${payMethodLabel}</td></tr>` : ''}
          ${balanceDue > 0 ? `<tr style="border-top:1px solid #bbf7d0;"><td style="padding:8px 0 0;color:#065f46;font-weight:700;">Balance Due</td><td style="padding:8px 0 0;color:#d97706;font-weight:700;">${fmt(balanceDue)}</td></tr>` : `<tr><td style="padding:5px 0;color:#065f46;font-weight:700;">Status</td><td style="padding:5px 0;color:#10b981;font-weight:700;">Fully Paid ✓</td></tr>`}
        </table>
      </div>

      ${balanceDue > 0 ? `
      <div style="background:#fffbeb;border:1px solid #fde68a;border-left:4px solid #f59e0b;border-radius:8px;padding:14px 16px;margin-bottom:24px;">
        <p style="margin:0;color:#92400e;font-size:13px;font-weight:600;">💡 Outstanding Balance</p>
        <p style="margin:6px 0 0;color:#78350f;font-size:13px;line-height:1.55;">
          You have an outstanding balance of <strong>${fmt(balanceDue)}</strong> which is due on or before your event date.
          Our team will be in touch to arrange payment.
        </p>
      </div>` : ''}

      <div style="text-align:center;margin:24px 0 20px;">
        <a href="mailto:bookings@venuedesk.co.uk"
           style="display:inline-block;background:#6366f1;color:#fff;text-decoration:none;padding:13px 32px;border-radius:8px;font-size:14px;font-weight:600;">
          Contact Us →
        </a>
      </div>

      <div style="border-top:1px solid #f3f4f6;padding-top:20px;margin-top:8px;">
        <p style="margin:0 0 3px;font-size:13px;color:#374151;font-weight:600;">VenueDesk Booking Team</p>
        <p style="margin:0 0 3px;font-size:12px;color:#6b7280;">📧 bookings@venuedesk.co.uk</p>
        <p style="margin:10px 0 0;font-size:11px;color:#9ca3af;">
          Please keep this email for your records. If any details are incorrect, contact us immediately.
        </p>
      </div>
    </div>
  </div>
</body></html>`;

return [{ json: { email: customer_email, subject, html, customer_name } }];
